let tkCur=null;
function openTk(ev,el){
  ev.stopPropagation();
  const d=TK[el.getAttribute('data-tk')]; if(!d) return;
  tkCur=d;
  document.getElementById('tkTtl').textContent=d.t;
  document.getElementById('tkLbls').innerHTML=d.l.map(x=>'<span class="tk-lbl">'+x+'</span>').join('');
  document.getElementById('tkZ').textContent=d.z;
  document.getElementById('tkU').innerHTML=tkUmsetzung(d).map(x=>'<li>'+x+'</li>').join('');
  document.getElementById('tkA').innerHTML=d.a.map(x=>'<li>'+x+'</li>').join('');
  document.getElementById('tkD').textContent=d.d;
  const b=document.getElementById('tkCp'); b.textContent='Als GitLab-Issue kopieren (Markdown)'; b.classList.remove('done');
  document.getElementById('tkDr').classList.add('on');
  document.getElementById('tkOv').classList.add('on');
  const ix=document.getElementById('tkIdx'); if(ix) ix.classList.remove('on');
  const xf=document.getElementById('tkxFt'); if(xf) xf.style.display='none';
  const cp=document.getElementById('tkCp'); if(cp) cp.style.display='';
  const hn=document.querySelector('.tk-hint'); if(hn) hn.style.display='';
  const dt=document.getElementById('tkDetail'); if(dt) dt.classList.remove('off');
  const ft=document.querySelector('.tk-ft'); if(ft) ft.style.display='flex';
}
function closeTk(){
  document.getElementById('tkDr').classList.remove('on');
  document.getElementById('tkOv').classList.remove('on');
}

function tkUmsetzung(d){
  if(d.u&&d.u.length) return d.u;
  if(d.mf){
    const el=document.getElementById(d.mf);
    if(el) return [...el.querySelectorAll('.sf-name')].map(x=>x.textContent.trim());
  }
  return [];
}
function tkMd(d){
  return '## '+d.t+'\n\n**Labels:** '+d.l.join(' · ')+'\n\n### Ziel\n'+d.z+
  '\n\n### Umsetzung\n'+tkUmsetzung(d).map(x=>'- '+x).join('\n')+
  '\n\n### Definition of Done\n'+d.a.map(x=>'- [ ] '+x).join('\n')+
  '\n\n### Abhängigkeiten\n'+d.d+'\n';
}
function copyTk(){
  if(!tkCur) return;
  const b=document.getElementById('tkCp');
  const done=()=>{b.textContent='In die Zwischenablage kopiert';b.classList.add('done');
    setTimeout(()=>{b.textContent='Als GitLab-Issue kopieren (Markdown)';b.classList.remove('done');},2200);};
  const txt=tkMd(tkCur);
  if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(txt).then(done).catch(()=>fb(txt,done));}
  else fb(txt,done);
}
function fb(txt,cb){const ta=document.createElement('textarea');ta.value=txt;ta.style.position='fixed';ta.style.opacity='0';
  document.body.appendChild(ta);ta.select();try{document.execCommand('copy');cb();}catch(e){}document.body.removeChild(ta);}

// ── Ticket-Index ──
function tkGroup(d){
  if(d.mf){ const el=document.getElementById(d.mf); if(el){ const a=el.closest('.area');
    if(a){ const n=a.querySelector('.area-name'); if(n) return n.textContent.trim(); } } }
  return (d.l&&d.l[0])?d.l[0]:'Weitere';
}
function openTkIndex(ev){
  if(ev) ev.preventDefault();
  document.getElementById('tkIdx').innerHTML =
    '<div class="tkx-bar">'+
    '<input class="tkx-search" id="tkxSearch" type="search" placeholder="Suchen — Titel, Bereich, Label…" oninput="tkRenderIndex(this.value)">'+
    '<button class="tkx-mini" onclick="tkSelAll()">Alle</button>'+
    '<button class="tkx-mini" onclick="tkSelNone()">Keine</button>'+
    '<span class="tkx-cnt" id="tkxCnt"></span></div><div id="tkIdxList"></div>';
  tkRenderIndex('');
  document.getElementById('tkIdx').classList.add('on');
  document.getElementById('tkDetail').classList.add('off');
  document.getElementById('tkBack').classList.remove('on');
  document.getElementById('tkTtl').textContent='Alle Umsetzungsbeschreibungen';
  document.getElementById('tkLbls').innerHTML='<span class="tk-lbl">'+Object.keys(TK).length+' Tickets</span>';
  document.getElementById('tkCp').style.display='none';
  document.querySelector('.tk-hint').style.display='none';
  document.getElementById('tkxFt').style.display='flex';
  document.querySelector('.tk-ft').style.display='flex';
  document.getElementById('tkDr').classList.add('on');
  document.getElementById('tkOv').classList.add('on');
}
function showTk(id){
  const el=document.createElement('span'); el.setAttribute('data-tk',id);
  openTk({stopPropagation:function(){}}, el);
  document.getElementById('tkIdx').classList.remove('on');
  document.getElementById('tkDetail').classList.remove('off');
  document.getElementById('tkBack').classList.add('on');
  document.querySelector('.tk-ft').style.display='flex';
}
document.addEventListener('DOMContentLoaded',function(){
  const n=document.getElementById('navTkN'); if(n) n.textContent=Object.keys(TK).length;
});


// ══ Ticket-Index mit Auswahl und Export ══
let tkSel = new Set();
function tkAreaOf(d){ return d.k || 'Weitere'; }
function tkRenderIndex(filter){
  const f=(filter||'').toLowerCase().trim();
  const grp={};
  for(const [id,d] of Object.entries(TK)){
    if(f && !(d.t.toLowerCase().includes(f) || tkAreaOf(d).toLowerCase().includes(f)
       || (d.l||[]).join(' ').toLowerCase().includes(f))) continue;
    const g=tkAreaOf(d); (grp[g]=grp[g]||[]).push([id,d]);
  }
  const names=Object.keys(grp).sort((a,b)=>grp[b].length-grp[a].length);
  let html='', shown=0;
  for(const g of names){
    html+='<div class="tki-grp">'+g+' · '+grp[g].length+'</div>';
    for(const [id,d] of grp[g]){
      shown++;
      const lab=(d.l||[]).find(x=>/Reifegrad|Status/i.test(x))||'';
      html+='<div class="tki-row'+(tkSel.has(id)?' sel':'')+'" id="row-'+id+'">'+
        '<input type="checkbox" class="tki-cb" '+(tkSel.has(id)?'checked':'')+' onchange="tkToggle(\''+id+'\',this.checked)" aria-label="Auswählen">'+
        '<button class="tki-open" onclick="showTk(\''+id+'\')"><span class="tki-t">'+d.t+'</span></button>'+
        (lab?'<span class="tki-l">'+lab+'</span>':'')+'</div>';
    }
  }
  if(!shown) html='<div style="padding:24px 4px;color:var(--gray);font-size:13px;">Keine Beschreibung gefunden.</div>';
  document.getElementById('tkIdxList').innerHTML=html;
  tkUpdCount();
}
function tkToggle(id,on){
  if(on) tkSel.add(id); else tkSel.delete(id);
  const r=document.getElementById('row-'+id); if(r) r.classList.toggle('sel',on);
  tkUpdCount();
}
function tkUpdCount(){
  const c=document.getElementById('tkxCnt'); if(c) c.innerHTML='<b>'+tkSel.size+'</b> von '+Object.keys(TK).length+' gewählt';
  const b=document.getElementById('tkxBtn'); if(b){ b.disabled=tkSel.size===0;
    b.textContent = tkSel.size ? ('Auswahl exportieren ('+tkSel.size+')') : 'Auswahl als GitLab-Datei exportieren'; }
}
function tkSelAll(){
  const f=(document.getElementById('tkxSearch')||{}).value||'';
  const ff=f.toLowerCase().trim();
  for(const [id,d] of Object.entries(TK)){
    if(ff && !(d.t.toLowerCase().includes(ff)||tkAreaOf(d).toLowerCase().includes(ff)
       ||(d.l||[]).join(' ').toLowerCase().includes(ff))) continue;
    tkSel.add(id);
  }
  tkRenderIndex(f);
}
function tkSelNone(){ tkSel.clear(); tkRenderIndex((document.getElementById('tkxSearch')||{}).value||''); }
function tkSelText(){
  let out='# amana Blueprint — GitLab-Issues\n\n_Export: '+tkSel.size+' Beschreibungen · '+new Date().toLocaleDateString('de-DE')+'_\n\n---\n\n';
  for(const id of Object.keys(TK)){ if(!tkSel.has(id)) continue; out+=tkMd(TK[id])+'\n---\n\n'; }
  return out;
}
function exportTk(){
  if(!tkSel.size) return;
  const blob=new Blob([tkSelText()],{type:'text/markdown;charset=utf-8'});
  const a=document.createElement('a');
  a.href=URL.createObjectURL(blob);
  a.download='amana-gitlab-issues-'+tkSel.size+'.md';
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  setTimeout(()=>URL.revokeObjectURL(a.href),1500);
  const b=document.getElementById('tkxBtn'); const t=b.textContent;
  b.textContent='Datei erzeugt'; b.classList.add('done');
  setTimeout(()=>{b.textContent=t;b.classList.remove('done');},2200);
}
function copySelTk(){
  if(!tkSel.size) return;
  const txt=tkSelText();
  if(navigator.clipboard&&navigator.clipboard.writeText) navigator.clipboard.writeText(txt).catch(()=>fb(txt,()=>{}));
  else fb(txt,()=>{});
  const b=document.getElementById('tkxBtn'); const t=b.textContent;
  b.textContent='In Zwischenablage kopiert'; b.classList.add('done');
  setTimeout(()=>{b.textContent=t;b.classList.remove('done');},2000);
}

document.addEventListener('keydown',e=>{if(e.key==='Escape')closeTk();});
